{
  "facts": [
    {
      "topic": "scope",
      "statement": "The target calls ZSTD_compressStream2 with continue, flush, and end directives, so strategy dispatch during streaming compression is within its operational surface.",
      "evidence": [
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 69,
          "end_line": 135,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The harness helper draws a strategy from ZSTD_STRATEGY_MIN through ZSTD_STRATEGY_MAX, adjusts the parameters, and sets the resulting strategy on the compression context.",
      "evidence": [
        {
          "unit_id": "u-194debf8ea4cd55b47ba",
          "start_line": 44,
          "end_line": 56,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-194debf8ea4cd55b47ba",
          "start_line": 101,
          "end_line": 110,
          "role": "dependency",
          "dependency_reason": "Passes the adjusted strategy to ZSTD_CCtx_setParameter."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "In the supplied before source, ZSTD_compressStream2 initializes compression from requested parameters; that initialization calls ZSTD_getCParamsFromCCtxParams, which passes the resulting parameters through ZSTD_adjustCParams_internal.",
      "evidence": [
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 6201,
          "end_line": 6235,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 6103,
          "end_line": 6129,
          "role": "dependency",
          "dependency_reason": "Shows the streaming initialization call that obtains compression parameters."
        },
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 1582,
          "end_line": 1595,
          "role": "dependency",
          "dependency_reason": "Shows parameter override followed by internal adjustment."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "The before-source block selector indexes compressor tables by strategy and dictionary mode, optionally uses a row-based table, and asserts that the selected compressor is nonnull.",
      "evidence": [
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 2990,
          "end_line": 3062,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "For a block large enough to attempt compression, the before-source sequence-store path invokes the selector for ordinary software compression and for fallback after an external sequence producer error.",
      "evidence": [
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 3153,
          "end_line": 3163,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 3277,
          "end_line": 3300,
          "role": "dependency",
          "dependency_reason": "Shows both calls to ZSTD_selectBlockCompressor."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "The before source provides conditional routes around block-compressor selection: small blocks skip compression, and a successful external sequence producer returns after copying its sequences. These routes must be considered when assessing a proposed failing witness.",
      "evidence": [
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 3153,
          "end_line": 3163,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 3233,
          "end_line": 3275,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-194debf8ea4cd55b47ba",
          "start_line": 156,
          "end_line": 164,
          "role": "dependency",
          "dependency_reason": "Shows that the harness helper can register or clear a sequence producer."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "The existing harness checks streaming compression return values for errors, then checks decompressed size and equality with the input. An error from an invoked compressor would fail an existing check.",
      "evidence": [
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 81,
          "end_line": 135,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 185,
          "end_line": 205,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-a7cd9e43defd8d40468a",
          "start_line": 40,
          "end_line": 47,
          "role": "dependency",
          "dependency_reason": "Defines error and assertion checks as aborting on failure."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The supplied build script delegates fuzzer compilation to tests/fuzz/fuzz.py; it does not itself establish the effective compressor-exclusion settings.",
      "evidence": [
        {
          "unit_id": "u-043cf5aa9ced10a35cb6",
          "start_line": 19,
          "end_line": 24,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    }
  ],
  "missing_information": [
    "The after-source ZSTD_adjustCParams_internal and ZSTD_selectBlockCompressor bodies are not supplied in this continuation.",
    "The delegated fuzz.py and Makefile build path, its effective compressor-exclusion definitions and defaults, and any relevant libzstd.mk settings are not supplied. Thus the frozen condition that the selected strategy is excluded is unestablished.",
    "The exclusion macro definitions and compressor entries under the effective build settings are needed to determine whether an excluded selection resolves to a callable compressor."
  ],
  "requested_symbols": [
    "ZSTD_adjustCParams_internal",
    "ZSTD_selectBlockCompressor"
  ],
  "requested_paths": [
    "tests/fuzz/fuzz.py",
    "tests/fuzz/Makefile",
    "lib/libzstd.mk",
    "lib/compress/zstd_compress.c"
  ]
}
